export default async function ingest({ events }, ctx) {
  const s = (await ctx.state.get("csrd-mail")) || {
    queue: [],
    seen: [],
    phase: "fetch",
    pending: null,
  };
  for (const e of events) {
    if (!e.messageId) throw Error("Missing message ID");
    if (!s.seen.includes(e.messageId) && !s.queue.some((x) => x.messageId === e.messageId))
      s.queue.push(e);
  }
  await ctx.state.set("csrd-mail", s);
  return { ok: true };
}

