export default async function next({ relayUrl, acknowledge, resolution }, ctx) {
  const s = await ctx.state.get("csrd-mail");
  if (!s) throw Error("Missing queue");
  if (!/^https:\/\//.test(relayUrl)) throw Error("Configure HTTPS relay URL");
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect unknown reply " + s.pending);
    if (resolution === "confirmed") {
      s.seen.push(s.queue[0].messageId);
      s.queue.shift();
      s.phase = "fetch";
    }
    s.pending = null;
    await ctx.state.set("csrd-mail", s);
  }
  const e = s.queue[0];
  if (!e)
    return {
      action: "done",
      messageId: ".",
      threadId: ".",
      url: relayUrl,
      request: {},
      facts: "",
      reply: "",
    };
  if (s.phase === "reply") {
    s.pending = "reply:" + e.messageId;
    await ctx.state.set("csrd-mail", s);
  }
  return {
    action: s.phase,
    messageId: e.messageId,
    threadId: s.threadId || ".",
    url: relayUrl,
    request: { messageId: e.messageId },
    facts: s.facts || "",
    reply: s.reply || "",
  };
}

