async function result({ kind, subject, threadId, statusCode, body, reply, sentMessageId }, ctx) {
  const s = await ctx.state.get("csrd-mail");
  if (!s?.queue?.length) throw Error("Missing mail state");
  const e = s.queue[0];
  if (kind === "fetch") {
    if (!subject.includes("CSRD Reporting")) {
      s.seen.push(e.messageId);
      s.queue.shift();
      s.phase = "fetch";
    } else {
      if (!threadId) throw Error("Missing thread ID");
      s.threadId = threadId;
      s.phase = "extract";
    }
  }
  if (kind === "extract") {
    if (statusCode !== 200 || typeof body?.text !== "string")
      throw Error("Attachment extraction failed");
    const content = body.text;
    function extractTags(tagName) {
      const regex = new RegExp(`<${tagName}[^>]*>(.*?)<\\/${tagName}>`, "gs");
      let matches = [],
        match;
      while ((match = regex.exec(content)) !== null) matches.push(match[1].trim());
      return matches;
    }
    const values = extractTags("ix:nonNumeric");
    s.facts = JSON.stringify({
      total_nonNumeric_tags: values.length,
      total_kpis_found: [
        "esrs:GHGScope1Emissions",
        "esrs:GHGScope2Emissions",
        "esrs:GHGScope3Emissions",
      ].filter((tag) => content.includes(tag)).length,
      empty_disclosures: (content.match(/<ix:nonNumeric[^>]*>\s*<\/ix:nonNumeric>/g) || []).length,
      governance_check: /<ix:nonNumeric[^>]*name="esrs:SustainabilityGovernance"/i.test(content)
        ? "PASS"
        : "MISSING",
      strategy_check: /<ix:nonNumeric[^>]*name="esrs:StrategySustainability"/i.test(content)
        ? "PASS"
        : "MISSING",
      header_check: /<ix:header>/i.test(content) ? "PASS" : "MISSING",
      duplicate_disclosures: [...new Set(values.filter((v, i, a) => a.indexOf(v) !== i))],
    });
    s.phase = "analyze";
  }
  if (kind === "analyze") {
    if (typeof reply !== "string" || !reply.trim()) throw Error("Empty AI reply");
    s.reply = reply;
    s.phase = "reply";
  }
  if (kind === "reply") {
    if (!sentMessageId) throw Error("Reply outcome unknown");
    s.pending = null;
    s.seen.push(e.messageId);
    s.queue.shift();
    s.phase = "fetch";
    delete s.reply;
    delete s.facts;
    delete s.threadId;
  }
  await ctx.state.set("csrd-mail", s);
  return { ok: true };
}

export default async function run(input, ctx) {
  return result({ ...input, kind: "fetch" }, ctx);
}

